317	fn termiosTimer(
318	    td_: ?*termio.Termio.ThreadData,
319	    _: *xev.Loop,
320	    _: *xev.Completion,
321	    r: xev.Timer.RunError!void,
322	) xev.CallbackAction {
323	    // log.debug("termios timer fired", .{});
324	
325	    // This should never happen because we guard starting our
326	    // timer on windows but we want this assertion to fire if
327	    // we ever do start the timer on windows.
328	    // TODO: support on windows
329	    if (comptime builtin.target.os.tag == .windows) {
330	        @panic("termios timer not implemented on Windows");
331	    }
332	
333	    _ = r catch |err| switch (err) {
334	        // This is sent when our timer is canceled. That's fine.
335	        error.Canceled => return .disarm,
336	
337	        else => {
338	            log.warn("error in termios timer callback err={}", .{err});
339	            @panic("crash in termios timer callback");
340	        },
341	    };
342	
343	    const td = td_.?;
344	    assert(td.backend == .exec);
345	    const exec = &td.backend.exec;
346	
347	    // This is kind of hacky but we rebuild a Pty struct to get the
348	    // termios data.
349	    const mode: ptypkg.Mode = (Pty{
350	        .master = exec.read_thread_fd,
351	        .slave = undefined,
352	    }).getMode() catch |err| err: {
353	        log.warn("error getting termios mode err={}", .{err});
354	
355	        // If we have an error we return the default mode values
356	        // which are the likely values.
357	        break :err .{};
358	    };
359	
360	    // If the mode changed, then we process it.
361	    if (!std.meta.eql(mode, exec.termios_mode)) mode_change: {
362	        log.debug("termios change mode={}", .{mode});
363	        exec.termios_mode = mode;
364	
365	        // We assume we're in some sort of password input if we're
366	        // in canonical mode and not echoing. This is a heuristic.
367	        const password_input = mode.canonical and !mode.echo;
368	
369	        // If our password input state changed on the terminal then
370	        // we notify the surface.
371	        {
372	            td.renderer_state.mutex.lockUncancelable(global.io());
373	            defer td.renderer_state.mutex.unlock(global.io());
374	            const t = td.renderer_state.terminal;
375	            if (t.flags.password_input == password_input) {
376	                break :mode_change;
377	            }
378	        }
379	
380	        // We have to notify the surface that we're in password input.
381	        // We must block on this because the balanced true/false state
382	        // of this is critical to apprt behavior.
383	        _ = td.surface_mailbox.push(.{
384	            .password_input = password_input,
385	        }, .{ .forever = {} });
386	    }
387	
388	    // Repeat the timer
389	    if (exec.termios_timer_running) {
390	        exec.termios_timer.run(
391	            td.loop,
392	            &exec.termios_timer_c,
393	            TERMIOS_POLL_MS,
394	            termio.Termio.ThreadData,
395	            td,
396	            termiosTimer,
397	        );
398	    }
399	
400	    return .disarm;
401	}
