 611	    const ArgsFormatter = struct {
 612	        args: []const [:0]const u8,
 613	
 614	        pub fn format(this: @This(), writer: *std.Io.Writer) std.Io.Writer.Error!void {
 615	            for (this.args, 0..) |a, i| {
 616	                if (i > 0) try writer.writeAll(", ");
 617	                try writer.print("`{s}`", .{a});
 618	            }
 619	        }
 620	    };
 621	
 622	    /// Initialize the subprocess. This will NOT start it, this only sets
 623	    /// up the internal state necessary to start it later.
 624	    pub fn init(gpa: Allocator, cfg: Config) !Subprocess {
 625	        // We have a lot of maybe-allocations that all share the same lifetime
 626	        // so use an arena so we don't end up in an accounting nightmare.
 627	        var arena = std.heap.ArenaAllocator.init(gpa);
 628	        errdefer arena.deinit();
 629	        const alloc = arena.allocator();
 630	
 631	        // Get our env. If a default env isn't provided by the caller
 632	        // then we get it ourselves.
 633	        var env = cfg.env;
 634	        errdefer env.deinit();
 635	
 636	        // If we have a resources dir then set our env var
 637	        if (cfg.resources_dir) |dir| {
 638	            log.info("found Ghostty resources dir: {s}", .{dir});
 639	            try env.put("GHOSTTY_RESOURCES_DIR", dir);
 640	        }
 641	
 642	        // Set our TERM var. This is a bit complicated because we want to use
 643	        // the ghostty TERM value but we want to only do that if we have
 644	        // ghostty in the TERMINFO database.
 645	        //
 646	        // For now, we just look up a bundled dir but in the future we should
 647	        // also load the terminfo database and look for it.
 648	        if (cfg.resources_dir) |base| {
 649	            try env.put("TERM", cfg.term);
 650	            try env.put("COLORTERM", "truecolor");
 651	
 652	            // Assume that the resources directory is adjacent to the terminfo
 653	            // database
 654	            var buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
 655	            const dir = try std.mem.print(&buf, "{s}/terminfo", .{
 656	                std.fs.path.dirname(base) orelse unreachable,
 657	            });
 658	            try env.put("TERMINFO", dir);
 659	        } else {
 660	            if (comptime builtin.target.os.tag.isDarwin()) {
 661	                log.warn("ghostty terminfo not found, using xterm-256color", .{});
 662	                log.warn("the terminfo SHOULD exist on macos, please ensure", .{});
 663	                log.warn("you're using a valid app bundle.", .{});
 664	            }
 665	
 666	            try env.put("TERM", "xterm-256color");
 667	            try env.put("COLORTERM", "truecolor");
 668	        }
 669	
 670	        // Add our binary to the path if we can find it.
 671	        ghostty_path: {
 672	            // Skip this for flatpak since host cannot reach them
 673	            if ((comptime build_config.flatpak) and
 674	                internal_os.isFlatpak())
 675	            {
 676	                break :ghostty_path;
 677	            }
 678	
 679	            var exe_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
 680	            const exe_bin_path = exe_buf[0 .. std.process.executablePath(
 681	                global.io(),
 682	                &exe_buf,
 683	            ) catch |err| {
 684	                log.warn("failed to get ghostty exe path err={}", .{err});
 685	                break :ghostty_path;
 686	            }];
 687	            const exe_dir = std.fs.path.dirname(exe_bin_path) orelse break :ghostty_path;
 688	            log.debug("appending ghostty bin to path dir={s}", .{exe_dir});
 689	
 690	            // We always set this so that if the shell overwrites the path
 691	            // scripts still have a way to find the Ghostty binary when
 692	            // running in Ghostty.
 693	            try env.put("GHOSTTY_BIN_DIR", exe_dir);
 694	
 695	            // Append if we have a path. We want to append so that ghostty is
 696	            // the last priority in the path. If we don't have a path set
 697	            // then we just set it to the directory of the binary.
 698	            if (env.get("PATH")) |path| {
 699	                // Verify that our path doesn't already contain this entry
 700	                var it = std.mem.tokenizeScalar(u8, path, std.fs.path.delimiter);
 701	                while (it.next()) |entry| {
 702	                    if (std.mem.eql(u8, entry, exe_dir)) break :ghostty_path;
 703	                }
 704	
 705	                try env.put(
 706	                    "PATH",
 707	                    try appendEnv(alloc, path, exe_dir),
 708	                );
 709	            } else {
 710	                try env.put("PATH", exe_dir);
 711	            }
 712	        }
 713	
 714	        // On macOS, export additional data directories from our
 715	        // application bundle.
 716	        if (comptime builtin.target.os.tag.isDarwin()) darwin: {
 717	            const resources_dir = cfg.resources_dir orelse break :darwin;
 718	
 719	            var buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
 720	
 721	            const xdg_data_dir_key = "XDG_DATA_DIRS";
 722	            if (std.mem.print(&buf, "{s}/..", .{resources_dir})) |data_dir| {
 723	                try env.put(
 724	                    xdg_data_dir_key,
 725	                    try appendEnv(
 726	                        alloc,
 727	                        env.get(xdg_data_dir_key) orelse "/usr/local/share:/usr/share",
 728	                        data_dir,
 729	                    ),
 730	                );
 760	        // This is not apprt-specific, so we do it here.
 761	        _ = env.orderedRemove("VTE_VERSION");
