 763	        // Setup our shell integration, if we can.
 764	        const shell_command: configpkg.Command = shell: {
 765	            const default_shell_command: configpkg.Command =
 766	                cfg.command orelse .{ .shell = switch (builtin.target.os.tag) {
 767	                    .windows => "cmd.exe",
 768	                    else => "sh",
 769	                } };
 770	
 771	            // Always set up shell features (GHOSTTY_SHELL_FEATURES). These are
 772	            // used by both automatic and manual shell integrations.
 773	            try shell_integration.setupFeatures(
 774	                &env,
 775	                cfg.shell_integration_features,
 776	                cfg.cursor_blink orelse true,
 777	            );
 778	
 779	            const force: ?shell_integration.Shell = switch (cfg.shell_integration) {
 780	                .none => {
