 782	                    // opt-in since it results in some Ghostty features not
 783	                    // working. We always want to log it.
 784	                    log.info("shell integration disabled by configuration", .{});
 785	                    break :shell default_shell_command;
 786	                },
 787	
 788	                .detect => null,
 789	                .bash => .bash,
 790	                .elvish => .elvish,
 791	                .fish => .fish,
 792	                .nushell => .nushell,
 793	                .zsh => .zsh,
 794	            };
