 812	            log.info(
 813	                "shell integration automatically injected shell={}",
 814	                .{integration.shell},
 815	            );
 816	
 817	            break :shell integration.command;
 818	        };
 819	
 820	        // Add the environment variables that override any others.
 821	        {
 822	            var it = cfg.env_override.iterator();
 823	            while (it.next()) |entry| try env.put(
 824	                entry.key_ptr.*,
 825	                entry.value_ptr.*,
 826	            );
 827	        }
