 679	            var exe_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
 680	            const exe_bin_path = exe_buf[0 .. std.process.executablePath(
 681	                global.io(),
 682	                &exe_buf,
 683	            ) catch |err| {
 684	                log.warn("failed to get ghostty exe path err={}", .{err});
 685	                break :ghostty_path;
 686	            }];
 687	            const exe_dir = std.fs.path.dirname(exe_bin_path) orelse break :ghostty_path;
