 801	            const integration = try shell_integration.setup(
 802	                alloc,
 803	                dir,
 804	                default_shell_command,
 805	                &env,
 806	                force,
 807	            ) orelse {
 808	                log.warn("shell could not be detected, no automatic shell integration will be injected", .{});
