231	        // Reset our signals
232	        var sa: posix.Sigaction = .{
233	            .handler = .{ .handler = posix.SIG.DFL },
234	            .mask = posix.sigemptyset(),
235	            .flags = 0,
236	        };
237	        posix.sigaction(posix.SIG.ABRT, &sa, null);
238	        posix.sigaction(posix.SIG.ALRM, &sa, null);
239	        posix.sigaction(posix.SIG.BUS, &sa, null);
240	        posix.sigaction(posix.SIG.CHLD, &sa, null);
241	        posix.sigaction(posix.SIG.FPE, &sa, null);
242	        posix.sigaction(posix.SIG.HUP, &sa, null);
243	        posix.sigaction(posix.SIG.ILL, &sa, null);
244	        posix.sigaction(posix.SIG.INT, &sa, null);
245	        posix.sigaction(posix.SIG.PIPE, &sa, null);
246	        posix.sigaction(posix.SIG.SEGV, &sa, null);
247	        posix.sigaction(posix.SIG.TRAP, &sa, null);
248	        posix.sigaction(posix.SIG.TERM, &sa, null);
249	        posix.sigaction(posix.SIG.QUIT, &sa, null);
250	
251	        // Create a new process group
252	        if (c.setsid() < 0) return error.ProcessGroupFailed;
253	
254	        // Set controlling terminal
255	        switch (posix.errno(c.ioctl(self.slave, c.TIOCSCTTY, @as(c_ulong, 0)))) {
256	            .SUCCESS => {},
257	            else => |err| {
258	                log.err("error setting controlling terminal errno={}", .{err});
259	                return error.SetControllingTerminalFailed;
260	            },
261	        }
262	
263	        // Can close master/slave pair now
264	        _ = posix.system.close(self.slave);
265	        _ = posix.system.close(self.master);
