449	    /// Helper to update the state and notify waiters via the cv.
457	    fn onExit(
458	        bus: ?*gio_c.GDBusConnection,
459	        _: [*c]const u8,
460	        _: [*c]const u8,
461	        _: [*c]const u8,
462	        _: [*c]const u8,
463	        params: ?*gio_c.GVariant,
464	        ud: ?*anyopaque,
465	    ) callconv(.c) void {
466	        const self = @as(*FlatpakHostCommand, @ptrCast(@alignCast(ud)));
467	        const state = state: {
468	            self.state_mutex.lockUncancelable(global.io());
469	            defer self.state_mutex.unlock(global.io());
470	            break :state self.state.started;
471	        };
472	
473	        var pid: u32 = 0;
474	        var exit_status_raw: u32 = 0;
475	        gio_c.g_variant_get(params.?, "(uu)", &pid, &exit_status_raw);
476	        if (state.pid != pid) return;
477	
478	        const exit_status = posix.W.EXITSTATUS(exit_status_raw);
479	        // Update our state
480	        self.updateState(.{
481	            .exited = .{
482	                .pid = pid,
483	                .status = exit_status,
484	            },
485	        });
486	        if (state.completion) |completion| {
487	            completion.result = exit_status;
488	            completion.timer.?.run(
489	                state.loop_xev.?,
490	                &completion.c_xev,
491	                0,
492	                anyopaque,
493	                completion.userdata,
494	                (struct {
495	                    fn callback(
496	                        ud_inner: ?*anyopaque,
497	                        l_inner: *xev.Loop,
498	                        c_inner: *xev.Completion,
499	                        r: xev.Timer.RunError!void,
500	                    ) xev.CallbackAction {
501	                        const c_outer: *Completion = @fieldParentPtr("c_xev", c_inner);
502	                        defer if (c_outer.timer) |*t| t.deinit();
503	
504	                        const result = if (r) |_| c_outer.result.? else |err| err;
505	                        c_outer.callback(ud_inner, l_inner, c_outer, result);
506	                        return .disarm;
507	                    }
508	                }).callback,
509	            );
510	        }
511	        log.debug("HostCommand exited pid={} status={}", .{ pid, exit_status });
512	
513	        // We're done now, so we can unsubscribe
514	        gio_c.g_dbus_connection_signal_unsubscribe(bus.?, state.subscription);
515	
516	        // We are also done with our loop so we can exit.
517	        gio_c.g_main_loop_quit(state.loop);
518	    }
