194	    pub const GetModeError = error{GetModeFailed};
195	
196	    pub fn getMode(self: Pty) GetModeError!Mode {
197	        var attrs: c.termios = undefined;
198	        if (c.tcgetattr(self.master, &attrs) != 0)
199	            return error.GetModeFailed;
200	
201	        return .{
202	            .canonical = (attrs.c_lflag & c.ICANON) != 0,
203	            .echo = (attrs.c_lflag & c.ECHO) != 0,
204	        };
205	    }
