296	fn fork() !posix.pid_t {
297	    const rc = posix.system.fork();
298	    switch (posix.errno(rc)) {
299	        .SUCCESS => return @intCast(rc),
300	        .AGAIN, .NOMEM => return error.SystemResources,
301	        else => |err| return posix.unexpectedErrno(err),
302	    }
303	}
